"""On-demand trial coverage audit. Never writes provider data into model inputs.

Only aggregate diagnostics leave memory. Trial scores/stats/odds are ignored.
Access and non-null fields do not establish accuracy, licensed production access,
complete historical absences, or confirmed starters.
"""
import datetime as dt
import json
import os
from pathlib import Path
import re
import unicodedata
import urllib.error
import urllib.request
from collections import Counter

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://api.sportsdata.io/v3/cfb/'
STATUSES = {'out', 'doubtful', 'questionable', 'probable'}
OL = {'C', 'G', 'T', 'OG', 'OT', 'OL'}
DL = {'DE', 'DT', 'DL', 'NT', 'EDGE', 'EDG'}


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def request_rows(path, key):
    # Fixed vendor origin, header authentication, and no credential-bearing redirects.
    if not re.fullmatch(r'(scores/json/(InjuredPlayers|Players|Teams)|stats/json/PlayerGameStatsByWeekFinal/\d{4}/10)', path):
        raise ValueError('Unsupported audit endpoint')
    request = urllib.request.Request(BASE + path, headers={
        'Ocp-Apim-Subscription-Key': key.strip(), 'Accept': 'application/json',
        'User-Agent': 'Darkhorse-Coverage-Audit/1.0'})
    opener = urllib.request.build_opener(NoRedirect)
    for attempt in range(2):
        try:
            with opener.open(request, timeout=25) as response:
                raw = response.read(20_000_001)
                if len(raw) > 20_000_000:
                    return {'state': 'response_too_large'}, []
                rows = json.loads(raw)
            if not isinstance(rows, list) or any(not isinstance(r, dict) for r in rows):
                return {'state': 'unexpected_response'}, []
            return {'state': 'returned_rows' if rows else 'empty_response', 'records': len(rows)}, rows
        except urllib.error.HTTPError as error:
            status = error.code
            error.close()
            if status in {500, 502, 503, 504} and attempt == 0:
                continue
            return {'state': {401: 'key_or_subscription_denied', 403: 'access_denied',
                              404: 'endpoint_or_sample_unavailable', 429: 'quota_or_rate_limit'}.get(status, 'http_error'),
                    'httpStatus': status}, []
        except (urllib.error.URLError, TimeoutError, OSError):
            return {'state': 'network_error'}, []
        except (ValueError, TypeError):
            return {'state': 'invalid_json'}, []


def summarize(rows):
    """Return counts only; never treat missing rows/statuses as healthy players."""
    statuses = Counter(str(r.get('InjuryStatus') or '').strip().lower() for r in rows)
    injured = [r for r in rows if str(r.get('InjuryStatus') or '').strip().lower() in STATUSES]
    return {
        'records': len(rows),
        'uniquePlayers': len({r['PlayerID'] for r in rows if r.get('PlayerID') is not None}),
        'teamsWithInjuryRows': len({r['TeamID'] for r in injured if r.get('TeamID') is not None}),
        'recognizedInjuryRows': len(injured),
        'missingStatusRows': statuses[''],
        'unrecognizedStatusRows': sum(v for k, v in statuses.items() if k and k not in STATUSES),
        'injuryRowsWithNotes': sum(bool(r.get('InjuryNotes')) for r in injured),
        'injuryRowsWithStartDate': sum(bool(r.get('InjuryStartDate')) for r in injured),
        'quarterbackInjuryRows': sum(r.get('Position') == 'QB' for r in injured),
        'centerInjuryRows': sum(r.get('Position') == 'C' for r in injured),
        'offensiveLineInjuryRows': sum(r.get('Position') in OL for r in injured),
        'defensiveLineInjuryRows': sum(r.get('Position') in DL for r in injured),
        'offensiveLineRows': sum(r.get('Position') in OL for r in rows),
        'outRows': statuses['out'],
        'confirmedStarters': 'not_provided',
        'modelUse': 'none',
    }


def norm(value):
    return ''.join(c for c in unicodedata.normalize('NFKD', str(value)).lower() if c.isalnum())


def compare_official(injured, provider_teams, availability):
    """Exact school/name matches only. Agreement is a spot-check, not validation."""
    official = {}
    for team in availability.get('teams', {}).values():
        if team.get('status') != 'reported':
            continue
        school = norm(team.get('teamName', ''))
        for player in team.get('players', []):
            name = norm(player.get('name', ''))
            if name and school:
                official.setdefault((school, name), []).append(norm(player.get('status', '')))
    schools = {t.get('TeamID'): norm(t.get('School', '')) for t in provider_teams}
    matches = same = different = 0
    for row in injured:
        name = norm(' '.join(str(row.get(k) or '') for k in ('FirstName', 'LastName')))
        candidates = official.get((schools.get(row.get('TeamID')), name), [])
        if len(candidates) != 1:
            continue
        matches += 1
        status = norm(row.get('InjuryStatus', ''))
        if status == candidates[0]:
            same += 1
        else:
            different += 1
    return {'exactSchoolAndNameMatches': matches, 'sameStatus': same,
            'differentOrIncomparableStatus': different,
            'officialSnapshotAt': availability.get('generatedAt'),
            'note': 'Existing official-report snapshot; dates and status definitions may differ. No automatic trust or model promotion.'}


def audit(key, fetch=request_rows):
    report = {'mode': 'trial_audit_only', 'checkedAt': dt.datetime.now(dt.timezone.utc).isoformat(),
              'keyConfigured': bool(key.strip()), 'modelInputsChanged': False,
              'productionReady': False, 'checks': [],
              'limits': ['Trial numeric statistics and odds are not used.',
                         'Successful requests do not prove complete or accurate injury coverage.',
                         'Player-game feeds omit players without a recorded statistic; absence is not proof of health or injury.',
                         'College starting lineups and replacement quality are not provided by these feeds.']}
    if not key.strip():
        report['status'] = 'key_missing'
        return report
    injury_state, injured = fetch('scores/json/InjuredPlayers', key)
    report['checks'].append({'check': 'current_injuries', **injury_state, **summarize(injured)})
    # Do not exhaust a trial quota after rejection; never print a response body.
    if injury_state['state'] in {'key_or_subscription_denied', 'access_denied', 'quota_or_rate_limit'}:
        report['status'] = 'blocked'
        return report
    team_state, teams = fetch('scores/json/Teams', key)
    report['checks'].append({'check': 'team_mapping', **team_state})
    if team_state['state'] == 'quota_or_rate_limit':
        report['status'] = 'partially_checked'
        return report
    if teams:
        try:
            official = json.loads((ROOT / 'availability.json').read_text())
            report['officialComparison'] = compare_official(injured, teams, official)
        except (OSError, ValueError):
            report['officialComparison'] = {'state': 'snapshot_unavailable'}
    year = dt.datetime.now(dt.timezone.utc).year
    for season in sorted({year - 1, year - 2, 2018}, reverse=True):
        state, rows = fetch(f'stats/json/PlayerGameStatsByWeekFinal/{season}/10', key)
        report['checks'].append({'check': 'historical_player_games', 'season': season, 'week': 10,
                                 **state, **summarize(rows)})
        if state['state'] in {'quota_or_rate_limit', 'key_or_subscription_denied', 'access_denied'}:
            break
    report['status'] = 'audit_complete' if all(x['state'] == 'returned_rows' for x in report['checks']) else 'partially_checked'
    return report


def main():
    # Raw provider data stays in process memory. Only sanitized aggregate diagnostics
    # are printed and placed in the Actions summary, never in the Pages artifact.
    report = audit(os.environ.get('SPORTSDATAIOAPIKEY', ''))
    safe = json.dumps(report, indent=2, allow_nan=False)
    print(safe)
    summary = os.environ.get('GITHUB_STEP_SUMMARY')
    if summary:
        with open(summary, 'a') as output:
            output.write('## SportsDataIO trial coverage audit\n\nNo trial data was added to model inputs.\n\n```json\n' + safe + '\n```\n')


if __name__ == '__main__':
    main()
